/**
 * Bootstrap 5 Dropdown & Navbar Toggle Native Handler
 */
document.addEventListener('DOMContentLoaded', function () {
  // Gère l'ouverture et la fermeture des Dropdowns (Menu déroulant)
  var dropdownElementList = document.querySelectorAll('[data-bs-toggle="dropdown"]');
  
  dropdownElementList.forEach(function (dropdownToggle) {
    dropdownToggle.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      
      var parent = this.closest('.dropdown') || this.parentElement;
      var menu = parent.querySelector('.dropdown-menu');

      // Ferme tous les autres menus ouverts
      document.querySelectorAll('.dropdown-menu.show').forEach(function (openMenu) {
        if (openMenu !== menu) {
          openMenu.classList.remove('show');
        }
      });

      // Bascule l'état affiché / caché
      if (menu) {
        menu.classList.toggle('show');
      }
    });
  });

  // Ferme le dropdown au clic n'importe où ailleurs sur la page
  document.addEventListener('click', function (e) {
    if (!e.target.matches('[data-bs-toggle="dropdown"]')) {
      document.querySelectorAll('.dropdown-menu.show').forEach(function (openMenu) {
        openMenu.classList.remove('show');
      });
    }
  });

  // Gère l'ouverture du menu Burger mobile (Collapse)
  var togglerList = document.querySelectorAll('[data-bs-toggle="collapse"]');
  togglerList.forEach(function (toggler) {
    toggler.addEventListener('click', function (e) {
      e.preventDefault();
      var targetId = this.getAttribute('data-bs-target') || this.getAttribute('href');
      if (targetId) {
        var targetEl = document.querySelector(targetId);
        if (targetEl) {
          targetEl.classList.toggle('show');
        }
      }
    });
  });
});